/// Implements the two-engine entry point generated by [`crate::main!`].
#[doc(hidden)]
#[macro_export]
macro_rules! __metabench_main {
    (
        criterion = $criterion_benchmarks:path,
        gungraun = { $($gungraun:tt)* },
        identities = $identities:expr
        $(, allocator = $allocator:path)?
        $(,)?
    ) => {
        $crate::__metabench_main!(
            @expand
            criterion = {
                factory = $crate::__private::default_criterion,
                benchmarks = $criterion_benchmarks,
            };
            criterion_unit = ::core::option::Option::Some("ns");
            gungraun = { $($gungraun)* };
            identities = $identities;
            allocator = [$($allocator)?];
        );
    };
    (
        criterion = {
            factory = $criterion_factory:path,
            benchmarks = $criterion_benchmarks:path,
            $( unit = $unit:literal, )?
        },
        gungraun = { $($gungraun:tt)* },
        identities = $identities:expr
        $(, allocator = $allocator:path)?
        $(,)?
    ) => {
        $crate::__metabench_main!(
            @expand
            criterion = {
                factory = $criterion_factory,
                benchmarks = $criterion_benchmarks,
            };
            criterion_unit = $crate::__metabench_main!(@unit $( $unit)?);
            gungraun = { $($gungraun)* };
            identities = $identities;
            allocator = [$($allocator)?];
        );
    };
    (@unit) => { ::core::option::Option::None };
    (@unit $unit:literal) => { ::core::option::Option::Some($unit) };

    (
        @expand
        criterion = {
            factory = $criterion_factory:path,
            benchmarks = $criterion_benchmarks:path,
        };
        criterion_unit = $criterion_unit:expr;
        gungraun = { $($gungraun:tt)* };
        identities = $identities:expr;
        allocator = [$($allocator:path)?];
    ) => {
        $crate::__metabench_main!(@allocator $($allocator)?);

        mod __metabench_criterion {
            use super::*;

            pub(super) fn run() {
                let mut criterion = $criterion_factory().configure_from_args();
                $criterion_benchmarks(&mut criterion);
                criterion.final_summary();
            }
        }

        mod __metabench_gungraun {
            use super::*;
            use $crate::__private::gungraun;

            $crate::__private::gungraun::main!($($gungraun)*);

            pub(super) fn run() {
                main();
            }
        }

        fn main() {
            if let Err(error) = $crate::__private::run(
                $crate::__private::EngineSet::both_with_unit(
                    __metabench_criterion::run,
                    __metabench_gungraun::run,
                    $criterion_unit,
                ),
                $identities,
                env!("CARGO_CRATE_NAME"),
            ) {
                eprintln!("metabench: {error}");
                ::std::process::exit(2);
            }
        }
    };
    (@allocator) => {
        #[global_allocator]
        static METABENCH_ALLOCATOR: $crate::__private::Allocator<::std::alloc::System> =
            $crate::__private::Allocator::system();
    };
    (@allocator $allocator:path) => {
        #[global_allocator]
        static METABENCH_ALLOCATOR: $crate::__private::Allocator<$allocator> =
            $crate::__private::Allocator::new($allocator);
    };
}
